function verificationLabel(s){return ({valid:'Valide techniquement',invalid:'Email invalide',accept_all:'Catch-all · incertain',unknown:'Résultat incertain',pending:'Vérification en cours',webmail:'Webmail · à contrôler',disposable:'Adresse jetable',blocked:'Opposition / traitement refusé',stale:'Vérification périmée'})[s]||'Email non vérifié'}
function maturityOptions(value){return [['unknown','Besoin inconnu'],['suspected','Hypothèse · 20/100'],['confirmed','Besoin confirmé · 50/100'],['project','Projet identifié · 75/100'],['purchasing','Achat en préparation · 100/100']].map(([k,v])=>`<option value="${k}" ${value===k?'selected':''}>${v}</option>`).join('')}
function contactSources(value){try{return JSON.parse(value||'[]').filter(v=>typeof v==='string').slice(0,5).map(url=>`<a target="_blank" rel="noopener noreferrer" href="${esc(safeLink(url))}">Source</a>`).join(' · ')}catch{return ''}}
function salesPanel(p){const t=p.tracking,v=p.verification;return `<section class="draft"><h2>Qualification et contact</h2><p><button data-action="contact-validation" data-id="${p.lead.id}">Vérifier / confirmer le décideur</button></p><div class="stats score-stats"><article class="stat"><small>Pertinence commerciale</small><strong>${p.scores.fit}/100</strong><p class="help">Appréciation de votre équipe ou hypothèse IA.</p></article><article class="stat"><small>Fiabilité de l’email</small><strong>${v?.reliability===null||!v?'—':v.reliability+'/100'}</strong><p class="help">${esc(verificationLabel(v?.status))}</p></article><article class="stat"><small>Maturité du besoin</small><strong>${p.scores.maturity===null?'—':p.scores.maturity+'/100'}</strong><p class="help">Renseignée par votre équipe.</p></article></div><p class="help">${v?'Adresse contrôlée : '+esc(v.email)+' · contrôle demandé le '+when(v.checked_at)+(v.provider_date?' · date fournisseur : '+esc(v.provider_date):''):"Aucune vérification technique effectuée pour l’adresse actuelle."} Une adresse valide n’est pas une preuve de consentement ni une garantie de livraison.</p><div class="actions"><button data-action="check-email" ${state.connections.hunter&&p.lead.email?'':'disabled'}>Vérifier l’email avec Hunter</button><select id="contact-department" aria-label="Fonction recherchée"><option value="">Toutes les fonctions</option><option value="procurement">Achats</option><option value="hr">Ressources humaines</option><option value="operations">Opérations / cible QHSE</option><option value="executive">Direction</option></select><button data-action="find-contacts" ${state.connections.hunter&&p.lead.website?'':'disabled'}>Chercher les contacts Hunter</button></div><p class="help">La recherche utilise le domaine du site enregistré. Les contacts sont proposés avec leurs sources, puis sélectionnés explicitement.</p>${p.contacts.map(c=>`<article class="result"><strong>${esc(c.full_name||'Adresse générique')} · ${esc(c.email)}</strong><p>${esc(c.position_text||'Fonction inconnue')} · ${esc(c.department)}</p><p class="help">Confiance de découverte Hunter : ${c.confidence===null?'inconnue':Number(c.confidence)+'/100'} · email à vérifier séparément. ${contactSources(c.sources)}</p><button data-action="apply-contact" data-id="${c.id}">Choisir ce contact</button></article>`).join('')}</section><section class="draft"><h2>Responsable et prochaine action</h2><form id="tracking-form"><input type="hidden" name="id" value="${p.lead.id}"><input type="hidden" name="version" value="${Number(t.version)}"><div class="grid">${field('contact_name','Nom de l’interlocuteur',t.contact_name,'text','maxlength="200"')}${field('contact_role','Fonction observée',t.contact_role,'text','maxlength="200"')}<label>Fonction cible<select name="target_function">${[['unknown','À identifier'],['procurement','Achats'],['hr','RH'],['qhse','QHSE'],['executive','Direction'],['other','Autre']].map(([k,v])=>`<option value="${k}" ${t.target_function===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Responsable commercial<select name="owner_id"><option value="">Non attribué</option>${state.team.map(u=>`<option value="${u.id}" ${Number(t.owner_id)===Number(u.id)?'selected':''}>${esc(u.email)}</option>`).join('')}</select></label><label>Maturité du besoin<select name="need_stage">${maturityOptions(t.need_stage)}</select></label>${field('due_date','Date de prochaine action',t.due_date||'','date')}${field('next_action','Prochaine action',t.next_action,'text','maxlength="500"')}${field('won_amount','Montant gagné réel (statut Gagné requis)',t.won_amount??'','number','min="0" step="0.001"')}<label>Devise du montant gagné<select name="won_currency">${[...new Set([...companyCurrencies(),p.lead.currency])].map(c=>`<option ${(t.won_currency||p.lead.currency)===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="pilot" value="1" ${Number(t.pilot)?'checked':''}>Inclure dans le pilote commercial</label></div><p class="help">Le pilote mesure les entreprises tunisiennes marquées, avec une cible de 50. Les relances sont des tâches de suivi ; aucun email n’est envoyé automatiquement.</p><div class="inline-error" role="alert"></div><div class="actions"><button class="primary">Enregistrer le suivi</button></div></form></section><section class="draft"><h2>Historique des échanges</h2><form id="interaction-form"><input type="hidden" name="id" value="${p.lead.id}"><div class="grid"><label>Type d’échange<select name="kind"><option value="call">Appel</option><option value="email">Email enregistré manuellement</option><option value="reply">Réponse reçue</option><option value="meeting">Rendez-vous</option><option value="note">Note</option></select></label>${field('date','Date de l’échange',new Date().toLocaleDateString('en-CA'),'date','required')}<label class="full">Compte rendu<textarea name="note" maxlength="5000" required></textarea></label></div><div class="inline-error" role="alert"></div><div class="actions"><button>Ajouter l’échange</button></div></form>${p.interactions.map(i=>`<article class="result"><strong>${esc({call:'Appel',email:'Email',reply:'Réponse reçue',meeting:'Rendez-vous',note:'Note'}[i.kind])} · ${when(i.occurred_at)}</strong><p>${esc(i.note)}</p><small>${esc(i.author)}</small></article>`).join('')||'<p class="muted">Aucun échange enregistré.</p>'}</section>`}
function salesView(){const m=state.metrics,won=m.won_amounts.map(t=>money(t.amount,t.currency)).join(' + ')||'—';return `<div class="heading"><div><div class="eyebrow">Suivi commercial</div><h1>Des contacts aux rendez-vous.</h1><p>Indicateurs cumulés : réponses et rendez-vous saisis par votre équipe, ventes réelles et actions à venir.</p></div></div><div class="stats"><article class="stat"><small>Réponses enregistrées · prospects distincts</small><strong>${m.replies}</strong></article><article class="stat"><small>Rendez-vous enregistrés · prospects distincts</small><strong>${m.meetings}</strong></article><article class="stat"><small>Emails techniquement valides · moins de 30 jours</small><strong>${m.verified_emails}</strong></article><article class="stat"><small>Montants gagnés saisis · devises séparées</small><strong>${esc(won)}</strong></article></div><article class="card"><h2>Pilote Tunisie : ${Number(m.pilot.total)}/50 entreprises</h2><p>${Number(m.pilot.qualified)} prospects avec un statut qualifié ou avancé. Marquez les fiches du pilote, puis mesurez vos contacts et résultats avant d’élargir la collecte.</p><p class="help">Coût saisi par prospect qualifié du pilote : ${m.pilot_costs.map(c=>c.per_qualified===null?'non calculable ('+c.currency+')':money(c.per_qualified,c.currency)).join(' / ')||'aucune dépense enregistrée'}. Les frais sont saisis manuellement ; ils ne sont pas synchronisés avec les factures fournisseurs.</p></article><article class="panel table-panel list"><div class="card-heading"><h2>Prochaines actions</h2></div><div class="scroll"><table><thead><tr><th>ÉCHÉANCE</th><th>PROSPECT</th><th>ACTION</th><th>RESPONSABLE</th><th></th></tr></thead><tbody>${m.tasks.map(t=>`<tr><td>${esc(t.due_date)}</td><td>${esc(t.name)}</td><td>${esc(t.next_action||'À préciser')}</td><td>${esc(t.owner_email||'Non attribué')}</td><td><button data-action="open-lead" data-id="${t.id}">Ouvrir</button></td></tr>`).join('')}</tbody></table></div>${m.tasks.length?'':'<div class="empty">Aucune prochaine action planifiée.</div>'}</article>${state.user.role==='owner'?`<article class="card list"><h2>Enregistrer une dépense</h2><form id="expense-form"><div class="grid">${field('provider','Fournisseur ou poste de dépense','','text','required maxlength="80"')}${field('amount','Montant payé','','number','required min="0.001" step="0.001" max="999999999.999"')}<label>Devise<select name="currency"><option>TND</option><option>EUR</option><option>USD</option></select></label>${field('date','Date de dépense',new Date().toLocaleDateString('en-CA'),'date','required')}${field('note','Note / référence facture','','text','maxlength="500"')}<label class="check"><input type="checkbox" name="pilot" value="1">Dépense du pilote Tunisie</label></div><div class="inline-error" role="alert"></div><div class="actions"><button>Enregistrer la dépense</button></div></form></article>`:''}<article class="card list"><h2>Dépenses saisies</h2>${state.expenses.map(e=>`<p>${esc(e.expense_date)} · ${esc(e.provider)} · ${money(e.amount,e.currency)} ${Number(e.pilot)?'· pilote':''}</p>`).join('')||'<p class="muted">Aucune dépense saisie.</p>'}</article>`}

function lockInterface(){state.busy=true;const elements=[...document.querySelectorAll('#app button:not(:disabled),#app input:not(:disabled),#app select:not(:disabled),#app textarea:not(:disabled),#dialog button:not(:disabled),#dialog input:not(:disabled),#dialog select:not(:disabled),#dialog textarea:not(:disabled)')];for(const e of elements)e.disabled=true;app.setAttribute('aria-busy','true');dialog.setAttribute('aria-busy','true');return ()=>{state.busy=false;for(const e of elements)if(e.isConnected)e.disabled=false;app.removeAttribute('aria-busy');dialog.removeAttribute('aria-busy')}}

function resetPrivateState(){Object.assign(state,{samples:null,sampleDetail:null,sampleDraft:null,sampleAnalysis:null,sampleQuery:'',sampleOrders:null,sampleLots:null,sampleProducts:[],sampleAnalysisSource:null,sampleAnalysisNotice:null});pilotClear();Object.assign(state,{b2b:null,crm:null,sourcing:null,sourcingResults:[],sourcingTab:'dashboard',duplicates:null,performance:null,inbox:null,today:null,todayScope:'mine',todayPage:1,admin:null,view:'leads',page:1,q:'',country:'',status:'',leads:[],total:0,totals:[],connections:{},searches:[],selected:null,drafts:[],results:[],jobs:[],selectedCandidate:null,team:[],profile:null,metrics:null,expenses:[],quote:null,opportunity:null,commerce:null,clientChoices:[]})}

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open')){document.body.classList.remove('menu-open');const b=document.querySelector('.menu-toggle');if(b){b.setAttribute('aria-expanded','false');b.focus()}}});
